///////////////////////////////////////////////////////////////////////

CCastleGate::CCastleGate() : CWeaponObject(0)
{
	m_Node = __IRR_SCENE()->addEmptySceneNode();
	
	setLevel(WL_None);
	reset();
}

CCastleGate::~CCastleGate()
{
	m_Node->remove();

	m_gate.getRoot()->remove();
	m_gate.getRoot()->drop();
}

///////////////////////////////////////////////////////////////////////

void CCastleGate::update(f32 time)
{
	CWeaponObject::update(time);

	if (m_slowHealth > m_health)
	{
		f32 acceleration = -1300.0f;
		m_slowHealthVelocity += acceleration * time;
		m_slowHealth += (m_slowHealthVelocity < -900.0f ? m_slowHealthVelocity : 0.0f) * time;
		if (m_slowHealth < m_health)
		{
			m_slowHealth = m_health;
			m_slowHealthVelocity = 0.0f;
		}
	}
}

void CCastleGate::reset()
{
	CWeaponObject::reset();

	m_health = m_maxHealth;
	m_slowHealth = m_maxHealth;
	m_slowHealthVelocity = 0.0f;
	m_gate.setAnim("stand", false);
	m_gate.getRoot()->setVisible(true);
}

void CCastleGate::damageGate(f32 damage)
{
	f32 oldHealth = m_health;
	damage = MIN(damage, m_health);
	if (damage > 0.0f)
	{
		m_health -= damage;
		CPlayfield::GetInstance()->getChallenge()->gateDamaged();

		if (m_health == 0.0f)
		{
			/// Just Destroyed
			m_gate.setAnim("fall", false);
			CPlayfield::GetInstance()->PlaySfx( SFX_CASTLE_DESTROY_GATE );
		}
		else if (oldHealth > m_maxHealth / 2 && m_health <= m_maxHealth / 2)
		{
			/// Just Deformed
			m_gate.setAnim("deform", false);
		}
		else
		{
			/// Hit
			if (m_health >= m_maxHealth / 2)
			{
				m_gate.setAnim("stand_hit", false, 1.5f);
			}
			else
			{
				m_gate.setAnim("deform_hit", false, 1.5f);
			}			
		}
	}
}

void CCastleGate::draw()
{
}

///////////////////////////////////////////////////////////////////////

void CCastleGate::adjustStats(IAttributes* attributes)
{
	m_maxHealth = attributes->getAttributeAsFloat("Health");

	ISceneNode * toBeDeleted = m_gate.getRoot();

	stringc file = attributes->getAttributeAsString("File");
	ISceneNode * node = LoadColladaScene( file.c_str() );
	cleanNode(node);
	m_Node->addChild(node);
	m_gate.setRoot(node);
	m_gate.setAnim("stand");	

	if (toBeDeleted)
	{
		toBeDeleted->remove();
		toBeDeleted->drop();
	}
}

void CCastleGate::setShopState()
{
	m_gate.setAnim("stand");
}
